-staff',])->exists(); @endphp @if($canSeeInstitutionLogin)<a href="{{ route('institution.login', $institution) }}" class="block px-4 py-3">Staff login</a>@endif</nav></aside><div class="min-w-0 space-y-6"><section id="overview" class="profile-anchor space-y-6 rounded-2xl border bg-white p-8"><h2 class="text-2xl font-bold">About the institution</h2><p class="leading-7 text-slate-600">@if($institution->slug === 'limkokwing-university-sierra-leone')Limkokwing University of Creative Technology, Sierra Leone is a Freetown-based institution offering programmes in creative technology, design, ICT, business and communications. The university combines academic study with practical, industry-focused learning.@elseif($institution->slug === 'university-b')University B is a Sierra Leone-focused higher education institution providing a general academic catalogue for undergraduates. It supports applications through UniGate and may publish faculties, programmes and admission cycles as the institution develops its profile.@else{{ $institution->name }} provides structured academic programmes and admissions services through UniGate. Applicants can review published programmes and entry requirements before beginning an application.@endif</p><div class="grid gap-4 sm:grid-cols-3"><div class="rounded-xl bg-slate-50 p-5"><p class="text-sm text-slate-500">Campus</p><p class="mt-2 font-bold">Freetown, Sierra Leone</p></div><div class="rounded-xl bg-slate-50 p-5"><p class="text-sm text-slate-500">Active programmes</p><p class="mt-2 text-2xl font-bold">{{ $institution->faculties->flatMap(fn ($faculty) => $faculty->departments->flatMap(fn ($department) => $department->programmes))->where('status','active')->count() }}</p></div><div class="rounded-xl bg-slate-50 p-5"><p class="text-sm text-slate-500">Open admissions</p><p class="mt-2 text-2xl font-bold">{{ $openCycles->count() }}</p></div></div></section><section id="programmes" class="profile-anchor mt-6 rounded-2xl border bg-white p-8"><h2 class="text-2xl font-bold">Programme catalogue</h2><div class="mt-6 space-y-5">@forelse($institution->faculties as $faculty)<article class="rounded-xl border p-5"><h3 class="text-lg font-bold text-blue-800">{{ $faculty->name }}</h3>@foreach($faculty->departments as $department)<div class="mt-4"><p class="text-sm font-bold text-slate-500">{{ $department->name }}</p><div class="mt-3 grid gap-3 md:grid-cols-2">@foreach($department->programmes->where('status','active') as $programme)<div class="rounded-lg bg-slate-50 p-4"><p class="font-semibold">{{ $programme->name }}</p><p class="mt-1 text-sm text-slate-500">{{ $programme->award_type }} · {{ $programme->duration_years }} years</p></div>@endforeach</div></div>@endforeach</article>@empty<p class="text-slate-500">No programmes are currently published.</p>@endforelse</div></section><section id="admission-requirements" class="profile-anchor mt-6 rounded-2xl border bg-white p-8"><h2 class="text-2xl font-bold">Admission requirements</h2><div class="mt-5 rounded-xl border border-blue-100 bg-blue-50 p-5"><h3 class="font-bold text-blue-900">General WASSCE requirement</h3><p class="mt-2 leading-7 text-slate-700">Applicants should normally have at least <strong>six credits</strong> in WASSCE or an accepted equivalent qualification, including <strong>English Language</strong> and <strong>Mathematics</strong>. Relevant science, business or creative subjects are required for many programmes.</p></div><ul class="mt-5 list-disc space-y-2 pl-5 text-slate-700"><li>For degree programmes: six WASSCE credits, including English Language and Mathematics, plus credits in relevant subjects.</li><li>For diploma programmes: at least four or five WASSCE credits depending on the programme.</li><li>Associate degree programmes: acceptable secondary school results and any subject prerequisites specified by the university.</li><li>Applicants may be required to attend an interview or submit a portfolio for creative and media programmes.</li><li>The university may request academic transcripts, certificates and a valid identification document before admission is confirmed.</li></ul></section></div></div></main></body></html>
